using System;
using System.Collections.Generic;
using System.Globalization;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;

public partial class Companion {
 TextBox calculatorInput;TextBlock calculatorResult,calculatorMessage;StackPanel calculatorHistory;
 bool calculatorJustEvaluated;string calculatorLastResult="0";
 readonly List<string[]> calculatorEntries=new List<string[]>();
 void CalculatorTab(){var panel=Stack();panel.Children.Add(Text("Калькулятор",17));panel.Children.Add(Text("Вводи с клавиатуры или нажимай кнопки.",11,"Muted"));var screen=Stack();calculatorInput=Input("Математическое выражение");calculatorInput.MaxLength=512;calculatorInput.FontFamily=new FontFamily("Consolas");calculatorInput.FontSize=22;calculatorInput.TextAlignment=TextAlignment.Right;calculatorInput.TextChanged+=(s,e)=>calculatorJustEvaluated=false;calculatorInput.KeyDown+=(s,e)=>{if(e.Key==Key.Enter){CalculateNow();e.Handled=true;}else if(e.Key==Key.Escape){ClearCalculator();e.Handled=true;}};calculatorInput.PreviewTextInput+=(s,e)=>{if(e.Text=="="){CalculateNow();e.Handled=true;}else if(calculatorJustEvaluated&&e.Text.Length==1&&"+-*/^%×÷−".Contains(e.Text)){calculatorInput.Text=calculatorLastResult+e.Text;calculatorInput.Select(calculatorInput.Text.Length,0);e.Handled=true;}};screen.Children.Add(calculatorInput);calculatorResult=Text("0",30,"Accent");calculatorResult.TextAlignment=TextAlignment.Right;calculatorResult.TextWrapping=TextWrapping.Wrap;screen.Children.Add(calculatorResult);calculatorMessage=Text("ENTER - результат · ESC - очистить",10,"Muted");screen.Children.Add(calculatorMessage);panel.Children.Add(Card(screen));
  var keys=new Grid();for(int i=0;i<4;i++)keys.ColumnDefinitions.Add(new ColumnDefinition());for(int i=0;i<6;i++)keys.RowDefinitions.Add(new RowDefinition{Height=new GridLength(46)});string[] labels={"C","⌫","(",")","%","÷","×","−","7","8","9","+","4","5","6","±","1","2","3","=","0",",","√","x²"};for(int i=0;i<labels.Length;i++){string key=labels[i];var button=Btn(key,()=>CalculatorKey(key),key=="=");button.FontSize=18;button.Padding=new Thickness(0);button.MinHeight=38;button.Margin=new Thickness(0,0,5,5);Grid.SetColumn(button,i%4);Grid.SetRow(button,i/4);keys.Children.Add(button);}panel.Children.Add(keys);panel.Children.Add(Text("200 + 10% = 220 · Запятая и точка - десятичный разделитель.",10,"Muted"));calculatorHistory=Stack();panel.Children.Add(calculatorHistory);Tab("Калькулятор",panel);
 }
 void ClearCalculator(){calculatorJustEvaluated=false;calculatorInput.Text="";calculatorResult.Text="0";calculatorMessage.Text="ENTER - результат · ESC - очистить";calculatorInput.Focus();}
 void InsertCalculator(string text){int at=calculatorInput.SelectionStart;int length=calculatorInput.SelectionLength;if(calculatorInput.Text.Length-length+text.Length>512)return;calculatorInput.Text=calculatorInput.Text.Remove(at,length).Insert(at,text);calculatorInput.Focus();calculatorInput.Select(at+text.Length,0);}
 void CalculatorKey(string key){if(key=="C"){ClearCalculator();return;}if(key=="="){CalculateNow();return;}if(key=="⌫"){int at=calculatorInput.SelectionStart,length=calculatorInput.SelectionLength;if(length>0){calculatorInput.Text=calculatorInput.Text.Remove(at,length);calculatorInput.Select(at,0);}else if(at>0){calculatorInput.Text=calculatorInput.Text.Remove(at-1,1);calculatorInput.Select(at-1,0);}calculatorInput.Focus();return;}if(key=="±"){calculatorInput.Text=calculatorInput.Text.Length==0?"-":"-("+calculatorInput.Text+")";calculatorInput.Focus();calculatorInput.Select(calculatorInput.Text.Length,0);return;}if(key=="√"||key=="x²"){string current=calculatorInput.Text.Trim();if(current.Length==0)current="0";calculatorInput.Text=key=="√"?"sqrt("+current+")":"("+current+")^2";CalculateNow();return;}if(calculatorJustEvaluated&&"+−×÷%".Contains(key)){calculatorInput.Text=calculatorLastResult;calculatorInput.Select(calculatorInput.Text.Length,0);}calculatorJustEvaluated=false;InsertCalculator(key);}
 void CalculateNow(){string expression=calculatorInput.Text.Trim();if(expression.Length==0){calculatorMessage.Text="Введи выражение для расчёта.";return;}try{double value=EvaluateCalculator(expression);string result=value.ToString("G15",CultureInfo.InvariantCulture);calculatorResult.Text=result;calculatorMessage.Text="РЕЗУЛЬТАТ";calculatorEntries.Insert(0,new[]{expression,result});if(calculatorEntries.Count>8)calculatorEntries.RemoveAt(8);calculatorHistory.Children.Clear();calculatorHistory.Children.Add(Text("Последние вычисления",14,"Muted"));foreach(var entry in calculatorEntries){string saved=entry[0];var button=Btn(entry[0]+" = "+entry[1],()=>{calculatorInput.Text=saved;calculatorInput.Focus();calculatorInput.Select(calculatorInput.Text.Length,0);});button.HorizontalContentAlignment=HorizontalAlignment.Left;button.Content=new TextBlock{Text=entry[0]+" = "+entry[1],TextWrapping=TextWrapping.Wrap,FontSize=11};calculatorHistory.Children.Add(button);}calculatorInput.Focus();calculatorInput.Select(0,calculatorInput.Text.Length);calculatorLastResult=result;calculatorJustEvaluated=true;}catch(Exception error){calculatorJustEvaluated=false;calculatorResult.Text="Ошибка";calculatorMessage.Text=error.Message;calculatorInput.Focus();}}
 public static double EvaluateCalculator(string expression){return new CalculatorParser(expression).Evaluate();}
 struct CalcValue {public double Number;public bool Percent;public CalcValue(double number,bool percent=false){Number=number;Percent=percent;}}
 class CalculatorParser {
  readonly string input;int index,depth;
  public CalculatorParser(string text){if(text==null||text.Length>512)throw new FormatException("Выражение слишком длинное.");input=text.Replace('×','*').Replace('÷','/').Replace('−','-').Replace(',','.');}
  void Space(){while(index<input.Length&&Char.IsWhiteSpace(input[index]))index++;}
  bool Take(char c){Space();if(index<input.Length&&input[index]==c){index++;return true;}return false;}
  static double Finite(double value){if(Double.IsNaN(value)||Double.IsInfinity(value))throw new ArithmeticException("Результат слишком большой или не является действительным числом.");return value;}
  public double Evaluate(){var value=Sum();Space();if(index!=input.Length)throw new FormatException("Проверь знак или скобки рядом с позицией "+(index+1)+".");return Finite(value.Number);}
  CalcValue Sum(){var left=Product();while(true){bool plus=Take('+');if(!plus&&!Take('-'))return left;var right=Product();double change=right.Percent?left.Number*right.Number:right.Number;left=new CalcValue(Finite(plus?left.Number+change:left.Number-change));}}
  CalcValue Product(){var left=Unary();while(true){bool multiply=Take('*');if(!multiply&&!Take('/'))return left;var right=Unary();if(!multiply&&right.Number==0)throw new DivideByZeroException("На ноль делить нельзя.");left=new CalcValue(Finite(multiply?left.Number*right.Number:left.Number/right.Number));}}
  CalcValue Unary(){if(++depth>64)throw new FormatException("Слишком много вложенных скобок или знаков.");try{if(Take('+'))return Unary();if(Take('-')){var value=Unary();return new CalcValue(-value.Number,value.Percent);}return Power();}finally{depth--;}}
  CalcValue Power(){var value=Postfix();if(Take('^'))value=new CalcValue(Finite(Math.Pow(value.Number,Unary().Number)));return value;}
  CalcValue Postfix(){var value=Primary();if(Take('%'))value=new CalcValue(value.Number/100,true);return value;}
  CalcValue Primary(){Space();if(Take('(')){var value=Sum();if(!Take(')'))throw new FormatException("Не хватает закрывающей скобки.");return value;}Space();if(index+4<=input.Length&&String.Equals(input.Substring(index,4),"sqrt",StringComparison.OrdinalIgnoreCase)){index+=4;if(!Take('('))throw new FormatException("После sqrt нужна открывающая скобка.");var value=Sum();if(!Take(')'))throw new FormatException("Не хватает закрывающей скобки.");if(value.Number<0)throw new ArithmeticException("Корень из отрицательного числа не является действительным.");return new CalcValue(Finite(Math.Sqrt(value.Number)));}int start=index;while(index<input.Length&&(Char.IsDigit(input[index])||input[index]=='.'))index++;if(index<input.Length&&(input[index]=='e'||input[index]=='E')){index++;if(index<input.Length&&(input[index]=='+'||input[index]=='-'))index++;while(index<input.Length&&Char.IsDigit(input[index]))index++;}double number;if(start==index||!Double.TryParse(input.Substring(start,index-start),NumberStyles.Float,CultureInfo.InvariantCulture,out number))throw new FormatException("Ожидается число рядом с позицией "+(start+1)+".");return new CalcValue(Finite(number));}
 }
}
